from fractions import Fraction
from typing import Sequence


def master_speedup(theta: Fraction, p_hit: Fraction) -> Fraction:
    """Speedup = 1 / (1 - (1 - theta) * P_hit)."""
    return 1 / (1 - (1 - theta) * p_hit)


def evaluate_filter(mu: Sequence[Fraction], hit: Sequence[bool], theta: Fraction) -> tuple[Fraction, Fraction]:
    """Return (P_hit, speedup) for a filter on a finite probability space."""
    assert sum(mu) == 1 and all(m >= 0 for m in mu)
    p_hit = sum((m for m, h in zip(mu, hit) if h), Fraction(0))
    return p_hit, master_speedup(theta, p_hit)


def which_factor_phit(alpha: Fraction, K: int, r: int = 2) -> Fraction:
    """Closed-form hit probability of an anonymous hint about one of r factors."""
    return (alpha + Fraction(r - 1, K)) / r


if __name__ == "__main__":
    mu = [Fraction(1, 4)] * 4
    print(evaluate_filter(mu, [True, True, False, False], Fraction(1, 2)))   # (1/2, 4/3)
    print(master_speedup(Fraction(1, 2), which_factor_phit(Fraction(1), 2)))  # 8/5

from fractions import Fraction


def ceiling(r: int, K: int) -> Fraction:
    """Anonymous perfect-hint ceiling with r factors at per-dial cost 1/K."""
    s = r - 1
    return Fraction((s + 1) * K * K, s * K * K - (s - 1) * K + s)


def best_dial(r: int, K_max: int = 1000) -> tuple[int, Fraction]:
    """Best dial size; for r >= 7 the answer is provably K = 2."""
    if r >= 7:
        return 2, Fraction(4 * r, 3 * r - 1)
    best_K = max(range(1, K_max + 1), key=lambda K: ceiling(r, K))
    return best_K, ceiling(r, best_K)


if __name__ == "__main__":
    for r in range(2, 12):
        K, v = best_dial(r)
        print(f"r={r:2d}: best K={K:4d}, ceiling={float(v):.4f}, limit r/(r-1)={r/(r-1):.4f}")

def noisy_work(theta: float, p: float, eps: float) -> float:
    """Fallback model: corrupted hint (prob eps) costs theta + 1, otherwise the master law."""
    return (1 - eps) * (1 - (1 - theta) * p) + eps * (1 + theta)


def alpha_star(theta: float, eps: float) -> float:
    """Break-even accuracy for an anonymous two-factor hint with P = (alpha + theta)/2."""
    return 2 * eps * theta / ((1 - eps) * (1 - theta)) - theta


def hint_helps(theta: float, eps: float, alpha: float) -> bool:
    return alpha > alpha_star(theta, eps)


def tolerances(theta: float) -> tuple[float, float]:
    """(internal, external) maximal noise levels at which filtering still pays."""
    return (1 - theta) / (2 - theta), (1 - theta**2) / (1 + 2 * theta - theta**2)


if __name__ == "__main__":
    print(tolerances(0.5))  # (1/3, 3/7)
    for th, ep, al in [(0.5, 0.1, 0.3), (0.5, 0.3, 0.5), (0.25, 0.4, 0.9)]:
        assert hint_helps(th, ep, al) == (noisy_work(th, (al + th) / 2, ep) < 1)
        print(th, ep, al, hint_helps(th, ep, al))
